{
  "name": "@khalilgharbaoui/opencode-colibri",
  "version": "0.1.1",
  "description": "opencode 2 provider plugin for a local Colibri server (coli serve)",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/khalilgharbaoui/opencode-colibri.git"
  },
  "homepage": "https://github.com/khalilgharbaoui/opencode-colibri#readme",
  "bugs": {
    "url": "https://github.com/khalilgharbaoui/opencode-colibri/issues"
  },
  "keywords": [
    "opencode",
    "colibri",
    "local-llm",
    "ai-sdk",
    "provider"
  ],
  "license": "MIT",
  "author": "Khalil Gharbaoui",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test test/*.test.ts"
  },
  "devDependencies": {
    "@ai-sdk/openai-compatible": "^2.0.88",
    "@ai-sdk/provider": "^3.0.19",
    "@types/node": "^25.9.9",
    "tsup": "^8.5.1",
    "tsx": "^4.23.15",
    "typescript": "^5.9.3"
  }
}
